187	    /**
188	     * Generate a customer code formatted {@code <LAST3>-<NNNN>}, where {@code LAST3} is the
189	     * upper-cased first three letters of {@code lastName} and {@code NNNN} is a global 4-digit
190	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
191	     *
192	     * @param lastName the owner's last name
193	     * @return the generated customer code
194	     */
195	    private String generateCustomerCode(String lastName) {
196	        String prefix = lastName.length() >= 3 ? lastName.substring(0, 3) : lastName;
197	        int sequence = this.clinicService.findAllOwners().size() + 1;
198	        return String.format("%s-%04d", prefix.toUpperCase(Locale.ROOT), sequence);
199	    }
200	
201	    /**
202	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
203	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
204	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
205	     * is returned lower-cased.
206	     *
207	     * @param email the raw email from the request payload, may be {@code null}
208	     * @return the lower-cased email, or {@code null} when none was provided
209	     */
210	    private String normalizeEmail(String email) {
211	        if (!StringUtils.hasText(email)) {
212	            return null;
213	        }
214	        if (!EMAIL_PATTERN.matcher(email).matches()) {
215	            throw new InvalidRequestException(List.of("email"));
216	        }
217	        return email.toLowerCase(Locale.ROOT);
218	    }
219	
220	    /**
221	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
222	     * already carries a leading '+' keeps its country code; otherwise the default country code
223	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
224	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
225	     * is thrown (mapped to 400 Bad Request).
226	     *
227	     * @param telephone the raw telephone from the request payload
228	     * @return the E.164 string (e.g. {@code +61412345678})
229	     */
230	    private String normalizeTelephone(String telephone) {
231	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
232	        String candidate;
233	        if (cleaned.startsWith("+")) {
234	            candidate = cleaned;
235	        } else {
236	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
237	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
238	        }
239	        if (!E164_PATTERN.matcher(candidate).matches()) {
240	            throw new InvalidRequestException(List.of("telephone"));
241	        }
242	        return candidate;
243	    }
244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Transactional
247	    @Override
248	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
249	        Owner owner = this.clinicService.findOwnerById(ownerId);
250	        if (owner == null) {
251	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
252	        }
253	        this.clinicService.deleteOwner(owner);
254	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
255	    }
256	
257	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
258	    @Override
259	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
260	        Owner owner = this.clinicService.findOwnerById(ownerId);
261	        if (owner == null) {
262	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
263	        }
264	        HttpHeaders headers = new HttpHeaders();
265	        Pet pet = petMapper.toPet(petFieldsDto);
266	        owner.setId(ownerId);
267	        pet.setOwner(owner);
268	        pet.getType().setName(null);
269	        this.clinicService.savePet(pet);
270	        PetDto petDto = petMapper.toPetDto(pet);
271	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
272	            .buildAndExpand(pet.getId()).toUri());
273	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
274	    }
275	
276	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
277	    @Override
278	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
279	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
280	        if (currentOwner != null) {
281	            Pet currentPet = this.clinicService.findPetById(petId);
282	            if (currentPet != null) {
283	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
284	                currentPet.setName(petFieldsDto.getName());
285	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
286	                this.clinicService.savePet(currentPet);
287	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
288	            }
289	        }
290	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
291	    }
292	
293	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
294	    @Override
295	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
296	        HttpHeaders headers = new HttpHeaders();
297	        Visit visit = visitMapper.toVisit(visitFieldsDto);
298	        Pet pet = new Pet();
299	        pet.setId(petId);
300	        visit.setPet(pet);
301	        this.clinicService.saveVisit(visit);
302	        VisitDto visitDto = visitMapper.toVisitDto(visit);
303	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
304	            .buildAndExpand(visit.getId()).toUri());
305	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
306	    }
307	
308	
309	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
310	    @Override
311	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
312	        Owner owner = this.clinicService.findOwnerById(ownerId);
313	        if (owner != null) {
314	            Pet pet = owner.getPet(petId);
315	            if (pet != null) {
316	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
317	            }
318	        }
319	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
320	    }
321	}
